INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(30101, 'Numbers 31:23', 'Numbers', 31, 23, 'او نور ټول هغه شیان چې نه سوځي، باید په سره اور کې واچول شي او هغه به پاک شي. خو هغه هم باید د هغو اوبو په وسیله پاک شي چې د پاکوالي دپاره کارول کیږي او هغه شیان چې په اور کې سوځي باید د اوبو په وسیله پاک شي.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30102, '2 Chronicles 4:7', '2 Chronicles', 4, 7, 'د پلان سره سم لس د سرو زرو څراغدانونه هم جوړ شول. سلیمان دا څراغدانونه د خدای د کور په منځ کې کېښودل. هغه د اصلي سالون دواړو خواوو ته پنځه، پنځه دانې څراغدانونه کېښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30103, '2 Chronicles 4:8', '2 Chronicles', 4, 8, 'هغه لس مېزونه هم جوړ کړل او په اصلي سالون کې یې کېښودل، یعنې دواړو خواوو ته یې پنځه، پنځه مېزونه کېښودل. بیا هغه د سرو زرو څخه سل دانې د وینې د شیندلو کاسې هم جوړې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30104, '2 Chronicles 4:11', '2 Chronicles', 4, 11, 'حورام همدارنګه تشتونه، بېلچې او د وینو د شیندلو کاسې جوړې کړې. نو حورام هغه کارونه پای ته ورسول چې د سلیمان پاچا دپاره یې د خدای د کور په خاطر په خپله غاړه اخیستي وو:', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30105, '2 Chronicles 4:12', '2 Chronicles', 4, 12, 'دوه ستنې. د ستنو په سرونو باندې د کاسو په شان دوه تاجونه. د جالیو دوه سېټونه، د ستنو په سرونو باندې د کاسو په شان دوه تاجونه د سینګارولو دپاره.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30106, '2 Chronicles 4:13', '2 Chronicles', 4, 13, 'د دوو سېټونو جالیو دپاره څلور سوه برنجي انار. د هرې جالۍ دپاره د برنجي انارو دوه قطارونه چې د ستنو په سرونو باندې د کاسو په شان تاجونه د ښکلا دپاره وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30107, '2 Chronicles 4:14', '2 Chronicles', 4, 14, 'هغه ګاډۍ د هغو د تشتونو سره هم جوړې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30108, '2 Chronicles 4:15', '2 Chronicles', 4, 15, 'ټانکۍ او د هغې لاندې دولس برنجي غویان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30109, '2 Chronicles 4:16', '2 Chronicles', 4, 16, 'د ایرو دپاره لوښي او همدارنګه بېلچې او د غوښې قاشق پنجې. د څښتن د کور ټول سامان چې حورام د سلیمان پاچا دپاره جوړ کړی ؤ، د صیقل شویو برنجو څخه ؤ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30110, 'Exodus 2:15', 'Exodus', 2, 15, 'کله چې فرعون د موسی د دې کار څخه خبر شو، هغه د موسی د وژلو هڅه وکړه. خو هغه د مدیان خاورې ته وتښتېده. یوه ورځ موسی د څاه په غاړه ناست ؤ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30111, 'Exodus 2:16', 'Exodus', 2, 16, 'چې د مدیان کاهن یترون اووه لورګانې راغلې چې اوبه راوباسي او د خپلې رمې دپاره اخورونه ډک کړي.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30112, 'Genesis 36:10', 'Genesis', 36, 10, 'د عیسو د زامنو نومونه دا دي: الیفاز د عیسو د ښځې عاده زوی او رعوییل د عیسو د ښځې بسمې زوی.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30113, 'Genesis 36:11', 'Genesis', 36, 11, 'د الیفاز زامن: تیمان، اومار، صفو، جعتام او قناز.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30114, 'Genesis 36:12', 'Genesis', 36, 12, 'تمناع د عیسو د زوی الیفاز وینځه وه او د هغې څخه د هغه زوی عمالیق پیدا شو. دا د عیسو د ښځې عادې لمسیان وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30115, 'Genesis 36:13', 'Genesis', 36, 13, 'د رعوییل زامن: نحت، زارح، شمه او مزه. دا د عیسو د ښځې بسمې لمسیان وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30116, 'Genesis 36:20', 'Genesis', 36, 20, 'دا د سعیر حوري زامن وو چې په هغې سیمه کې اوسېدل: لوتان، شوبال، صبعون، عنه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30117, 'Genesis 36:21', 'Genesis', 36, 21, 'دیشون، ایصر او دیشان. دا په ادوم کې د سعیر زامن او د حوریانو مشران وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30118, 'Genesis 36:25', 'Genesis', 36, 25, 'د عنه اولادونه: دیشون او اهولیبامه د عنه لور.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30119, 'Genesis 36:26', 'Genesis', 36, 26, 'د دیشون زامن: حمدان، اشبان، یتران او کران.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30120, 'Genesis 36:29', 'Genesis', 36, 29, 'دا د حوریانو مشران وو: لوتان، شوبال، صبعون، عنه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30121, 'Genesis 36:30', 'Genesis', 36, 30, 'دیشون، ایصر او دیشان. دا د حوریانو قبیلې وې چې د ادوم په خاوره کې اوسېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30122, 'Judges 14:12', 'Judges', 14, 12, 'شمشون هغوی ته وویل: «اجازه راکړئ چې تاسو ته یوه معما ووایم. که چېرې تاسو ماته د مېلمستیا په اووه ورځو کې د هغې ځواب راکړ، زه به تاسو ته د کتان دېرش جوړې ساده کالي او دېرش جوړې ښکلي کالي درکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30123, 'Judges 14:13', 'Judges', 14, 13, 'خو که چېرې تاسو ځواب رانه کړ، تاسو باید ماته دېرش جوړه د کتان ساده کالي او دېرش جوړه ښکلي کالي راکړئ.» هغوی ورته وویل: «ته خپله معما مونږ ته ووایه چې مونږ یې واورو.»', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30124, 'Song of Songs 6:1', 'Song of Songs', 6, 1, 'ستا جانان چرته لاړونه، په ټولو پېغلو کښې ښائسته جينۍ؟ ستا جانان چرته تلے دېنه؟ چې مونږ تا سره د هغۀ تلاش وکړونه؟ محبوبه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30125, 'Song of Songs 6:2', 'Song of Songs', 6, 2, 'زما جانان خپل باغ ته راغلے دېنه، خپل د خوشبويانو کټ ته، چې خپله رمه په باغونو کښې وڅروينه، او د لاله ګلونه ترې نه راټول کړينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30126, 'Song of Songs 6:3', 'Song of Songs', 6, 3, 'جانان زما او زۀ د جانان يمه، هغه چې د لاله په ګلونو کښې مزې کوينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30127, 'Song of Songs 6:4', 'Song of Songs', 6, 4, 'زما محبوبې، تۀ لکه د تِرضاه د ښار په شان ښائسته ينه. آو، لکه د يروشلم په شان ښائسته ينه، او په يو ځل ليدو دې ما نه زړګے وړے دېنه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30128, 'Song of Songs 6:5', 'Song of Songs', 6, 5, 'سترګې دې ما نه واړوه، ځکه چې زۀ يې بې‌وسه کړے يمه. ستا زلفى وَل وَل لکه د چېلو د رمو په شان دينه، چې د جِلعاد د غرۀ نه لاندې راکوزيږينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30129, 'Song of Songs 6:6', 'Song of Songs', 6, 6, 'ستا غاښونه د سپينو ګډو په شان دينه، چې تازه ترې نه وړۍ اخوا شوې وينه، او تازه لمبولے شوے وينه. هر يو غاښ دې د بل سره جوړه دېنه، يو هم کنډم شوے نۀ دېنه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30130, 'Song of Songs 6:7', 'Song of Songs', 6, 7, 'ستا اننګى د نقاب شاته لکه د ګلابى انار ځليږينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30131, 'Song of Songs 6:8', 'Song of Songs', 6, 8, 'په شپېتو مَلِکو او په اتيا وينځو کښې او په بې‌شمېره پېغلو کښې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30132, 'Song of Songs 6:9', 'Song of Songs', 6, 9, 'خو زۀ به بيا هم خپله ګوګوشتکه خوښومه، زما کامله مينه، د خپلې مور ډېره خوښه ده نه، او د هغه چا ډېره نيازبينه چا چې زيږولې ده نه. پېغلې هغه وينى او د هغې صِفت کوينه، تر دې چې شهزادګۍ او شاهى وينځې د هغې د صِفت سندرې وائينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30133, 'Song of Songs 6:10', 'Song of Songs', 6, 10, '”دا څوک ده چې لکه د سحر د رڼا په شان راوچتيږينه، لکه د سپوږمۍ په شان ښائسته، او د نمر په شان ځليږينه، او په يو ځل ليدو دې ما نه زړګے وړے دېنه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30134, 'Song of Songs 6:11', 'Song of Songs', 6, 11, 'زۀ د غوزانو باغ ته لاړمه او وادۍ ته د ګلونو د غوټو سيل ته لاړمه، د انګورو د ځيلو راټوکېدل ووينمه او چې انارو ګلونه کړى دى کۀ نه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30135, 'Song of Songs 6:12', 'Song of Songs', 6, 12, 'زۀ په خپل ځان نۀ پوهېدمه، او د عشق نه رپېدمه لکه چې په شاهى ګاډۍ کښې سور يمه ښځې', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30136, 'Song of Songs 6:13', 'Song of Songs', 6, 13, 'واپس راشه، مونږ ته راواپس شه، اے د شولم پېغلې. واپس راشه، واپس راشه چې مونږ تا دوباره وګورونه. محبوب تاسو د شولم دې پېغلې ته ولې ګورئينه کله چې هغه د ګډېدونکو د دوه صفونو په مينځ کښې ډېره ښائسته ګډيږينه؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30137, '1 Samuel 1:9', '1 Samuel', 1, 9, 'یوځل کله چې هغوی په شیلوه کې د څښتن په کور کې د خوړلو او څښلو څخه وزګار شول، حنا پاڅېدله. په دې وخت کې عیلي کاهن د څښتن د کور په دروازه کې په خپلې چوکۍ باندې ناست ؤ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30138, '1 Samuel 1:10', '1 Samuel', 1, 10, 'حنا ډېره خفه وه او ډېر سخت یې وژړل او څښتن ته یې دعا وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30139, 'Judges 19:12', 'Judges', 19, 12, 'خو بادار یې وویل: «نه، مونږ په دې پردي ښار کې چې اسراییلیان په کې نشته نه پاتې کېږو. مونږ به جبعې ته لاړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30140, 'Judges 19:13', 'Judges', 19, 13, 'راځئ کوښښ وکړو چې جبعې یا رامه ته ځانونه ورسوو او د دې دواړو ځایونو څخه په یو ځای کې شپه تېره کړو.»', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30141, '2 Samuel 23:24', '2 Samuel', 23, 24, 'په دېرش کسیزه ډله کې دغه کسان وو: عساهیل د یوآب ورور. الحانان د دودو زوی د بیت لحم څخه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30142, '2 Samuel 23:25', '2 Samuel', 23, 25, 'شمه او الیقا د حرود څخه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30143, '2 Samuel 23:26', '2 Samuel', 23, 26, 'حالز فلتي. عیرا د عقیش زوی د تقوع څخه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30144, '2 Samuel 23:27', '2 Samuel', 23, 27, 'ابیعزر د عناتوت څخه. مبونای د حوشا څخه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30145, '2 Samuel 23:28', '2 Samuel', 23, 28, 'صلمون د اخوخ څخه. مهرای د نطوفې څخه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30146, '2 Samuel 23:29', '2 Samuel', 23, 29, 'حالب د بعنه زوی د نطوفې څخه. اتای د ریبای زوی د بنیامین د جبعې څخه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30147, '2 Samuel 23:30', '2 Samuel', 23, 30, 'بنایاه د فرعاتون څخه. هدای د جاعش د خوړونو څخه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30148, '2 Samuel 23:31', '2 Samuel', 23, 31, 'ابي علبون د عربات څخه. عزموت د بحوریم څخه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30149, '2 Samuel 23:32', '2 Samuel', 23, 32, 'الیحبا د شعلبون څخه. د یاشن زامن. یوناتان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30150, '2 Samuel 23:33', '2 Samuel', 23, 33, 'شمه د حرار څخه. اخیام د شارر زوی د حرار څخه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30151, '2 Samuel 23:34', '2 Samuel', 23, 34, 'الیفلط د احسبای زوی د معکې څخه. الیعام د اخیتوفل زوی د جیلوه څخه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30152, '2 Samuel 23:35', '2 Samuel', 23, 35, 'حزرای د کرمل څخه. فعرای اربي.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30153, '2 Samuel 23:36', '2 Samuel', 23, 36, 'یجال د ناتان زوی د صوبې څخه. باني د جاد څخه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30154, '2 Samuel 23:37', '2 Samuel', 23, 37, 'صالق د عمون څخه نحرای د بیروت څخه چې د زرویه د زوی یعنې د یوآب وسلې به یې وړلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30155, '2 Samuel 23:38', '2 Samuel', 23, 38, 'عیرا او جارب له یتر څخه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30156, '2 Samuel 23:39', '2 Samuel', 23, 39, 'اوریا حیتي. دا ټول اووه دېرش کسان وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30157, '1 Kings 1:5', '1 Kings', 1, 5, 'نو د داود زوی ادونیا چې مور یې حجیت نومېدله، هغه د پاچاهۍ دعوه وکړه. نو هغه څو جنګي ګاډۍ، اسونه او پنځوس کسان د بدرګې دپاره ځان ته تیار کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30158, '1 Kings 1:6', '1 Kings', 1, 6, 'پلار یې داود د ده په کارونو کې هېڅکله لاس وهنه نه کوله. پرته له دې، هغه ډېر ښکلی ځوان ؤ او د ابشالوم څخه وروسته د هغه مشر زوی ؤ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30159, 'Leviticus 13:40', 'Leviticus', 13, 40, 'که چېرې یو سړي خپل ویښتان له لاسه ورکړي وي او ګنجی شوی وي، هغه پاک دی.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30160, 'Leviticus 13:41', 'Leviticus', 13, 41, 'که چېرې هغه د خپلې کوپړۍ یا تندي ویښتان له لاسه ورکړي وي او لوڅ تندی ولري، هغه پاک دی.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30161, 'Leviticus 13:47', 'Leviticus', 13, 47, 'که چېرې کوم کالي چڼاسکې وهلي وي، که هغه د وړیو څخه جوړ شوي وي یا د کتان کالي وي،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30162, 'Leviticus 13:48', 'Leviticus', 13, 48, 'د کتان یا وړیو ټوکر، یا څرمن او یا داسې شی وي چې د څرمنې څخه جوړ شوی وي،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30163, 'Song of Songs 3:1', 'Song of Songs', 3, 1, 'ټوله شپه کله چې زۀ په خپل کټ کښې پرته ومه، د چا سره چې زۀ مينه کوم ما د هغۀ لټون وکړونه، خو هغه رانۀ غلونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30164, 'Song of Songs 3:2', 'Song of Songs', 3, 2, 'خو بيا ما خپل ځان ته ووئيل، زۀ به پاڅېږمه او ټول ښار به ولټومه، د هغه چا پسې به په چوکونو او سړکونو کښې وګرځېږمه چا سره چې زۀ مينه کومه. نو زۀ ورپسې ښۀ وګرځېدمه خو پېدا مې نۀ کړونه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30165, 'Song of Songs 3:3', 'Song of Songs', 3, 3, 'چوکيدارانو زۀ ودرولمه، کله چې هغوئ په ښار کښې ګرځېدل. ما د هغوئ نه تپوس وکړلو، ”ولې تاسو هغه کس ليدلے دېنه چا سره چې زۀ مينه کومه؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30166, 'Song of Songs 3:4', 'Song of Songs', 3, 4, 'نو چې د هغوئ نه لږ وړاندې لاړمه ما خپل جانان پېدا کړونه. هغه مې راټينګ کړونه او تلو ته مې پرې نۀ‎ ښودلونه او ما هغه د خپلې مور کور ته راوستونه هغې کوټې ته په کومه کښې چې زۀ د مور په ګېډه شوې ومه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30167, 'Song of Songs 3:5', 'Song of Songs', 3, 5, 'اے د يروشلم جينکو، ما سره ټينګه وعده وکړئينه، ترڅو چې مونږ پراتۀ يونه مونږ به نۀ په عذابوئينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30168, 'Song of Songs 3:6', 'Song of Songs', 3, 6, 'چې د لوګى د ستن په شان دے هغه څوک دېنه هغه زمونږ طرف ته راروان دېنه؟ چې فضا يې په مُر او لوبانو خوشبوداره کړې ده نه، او د سوداګرو په عطرو باندې خوشبوداره کړې ده نه؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30169, 'Song of Songs 3:7', 'Song of Songs', 3, 7, 'دا د سليمان ګاډۍ ده وګورئينه، چې ورسره شپېتۀ تکړه کسان په پرګله کښې راروان دينه، د بنى اِسرائيلو د ټولو نه ښۀ فوجيان ورسره دينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30170, 'Song of Songs 3:8', 'Song of Songs', 3, 8, 'هغوئ ټول په تُورو باندې سمبال دينه، او په جنګ کښې هم ماهر دينه، هر يو سره په ترخ کښې تُوره ده، او هغوئ په شپه کښې د بادشاه د حفاظت کولو جوګه هم دينه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30171, 'Song of Songs 3:9', 'Song of Songs', 3, 9, 'سليمان بادشاه شاهى ګاډۍ ځان دپاره د لبنان د دِيار د لرګو نه جوړه کړې ده نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30172, 'Song of Songs 3:10', 'Song of Songs', 3, 10, 'د هغې ستنې هغۀ د سپينو زرو نه جوړې کړې دينه، او د هغې چت يې د سرو زرو نه جوړ کړے دېنه، او د هغې بالښتونه کاسنى دينه. هغه د يروشلم د پېغلو په مينې سره ښائسته شوې وه نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30173, 'Song of Songs 3:11', 'Song of Songs', 3, 11, 'اے د يروشلم پېغلو راشئ کنه، او سليمان بادشاه وګورئينه هغۀ هغه تاج په سر کړے دېنه کوم چې د وادۀ په ورځ مور ورکړے وونه، ډېره د خوشحالۍ ورځ وه د هغۀ د ټولو نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30174, 'Genesis 22:22', 'Genesis', 22, 22, 'او د هغې نور پنځه زامن دا وو: کاسد، حزو، فلداش، یدلاف او بتوییل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30175, 'Genesis 22:23', 'Genesis', 22, 23, 'د بتوییل څخه ربکا پیدا شوه. میلکې د ابراهیم ورور ناحور ته دا اته زامن وزېږول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30176, 'Ezra 8:4', 'Ezra', 8, 4, 'الیهوعینای د زرحیا زوی د دوو سوو تنو سره د فحت موآب له طایفې څخه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30177, 'Ezra 8:5', 'Ezra', 8, 5, 'شکنیا د یحزییل زوی د درېو سوو تنو سره د زتو له طایفې څخه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30178, 'Ezra 8:6', 'Ezra', 8, 6, 'عابد د یوناتان زوی د پنځوسو تنو سره د عادین له طایفې څخه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30179, 'Ezra 8:7', 'Ezra', 8, 7, 'اشعیا د عتلیا زوی د اویاو تنو سره د عیلام له طایفې څخه', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30180, 'Ezra 8:8', 'Ezra', 8, 8, 'زبدیا د میکاییل زوی د اتیاو تنو سره د شفطیا له طایفې څخه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30181, 'Ezra 8:9', 'Ezra', 8, 9, 'عوبدیا د یحییل زوی د دوو سوو اتلسو تنو سره د یوآب له طایفې څخه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30182, 'Ezra 8:10', 'Ezra', 8, 10, 'شلومیت د یوسفیا زوی د یوسلو شپېتو تنو سره د باني له طایفې څخه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30183, 'Ezra 8:11', 'Ezra', 8, 11, 'زکریا د ببای زوی د اته ویشتو تنو سره د ببای له طایفې څخه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30184, 'Ezra 8:12', 'Ezra', 8, 12, 'یوحانان د هقاتان زوی د یوسلو لسو کسانو سره د عزجد له طایفې څخه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30185, 'Ezra 8:13', 'Ezra', 8, 13, 'الیفلط، یوییل، شمعیه د شپېتو کسانو سره د ادونیقام له طایفې څخه. دوی وروسته راستانه شوي دي.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30186, 'Ezra 8:14', 'Ezra', 8, 14, 'عوتای او ذکور د اویاو کسانو سره د بغوای له طایفې څخه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30187, '1 Samuel 9:9', '1 Samuel', 9, 9, 'په پخوا زمانه کې چې کله به په اسراییلو کې چا غوښتل چې د خدای څخه سوال وکړي، نو داسې به یې ویل: «راځئ چې غیب ویونکي ته ورشو.» ځکه چې اوسنی نبي به پخوا د غیب ویونکي په نوم یادېده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30188, '1 Samuel 9:10', '1 Samuel', 9, 10, 'شاوول خپل نوکر ته وویل: «ښه خبره ده، راځه چې ځو.» نو دوی هغه ښار ته لاړل چې نبي په کې ؤ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30189, '1 Samuel 9:11', '1 Samuel', 9, 11, 'هغه وخت چې هغوی ښار ته په غونډۍ باندې پورته کېدل، ویې لیدل چې یو څو نجونې د اوبو وړلو دپاره راروانې دي. د هغوی څخه یې پوښتنه وکړه: «ایا غیب ویونکی دلته دی؟»', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30190, '1 Samuel 9:12', '1 Samuel', 9, 12, 'هغوی ځواب ورکړ: «هو، هغه ستاسو څخه مخکې روان دی، زر کوئ هغه نن زمونږ ښار ته راغلی دی، ځکه چې نن ورځ خلک د عبادت په ځای کې چې په غونډۍ باندې ده قرباني کوي.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30191, '1 Samuel 9:13', '1 Samuel', 9, 13, 'څنګه چې تاسو ښار ته ننوځئ، نو مخکې له دې چې هغه د عبادت ځای ته د خوړلو دپاره پورته وخېژي، تاسو به یې پیدا کړئ. ترڅو پورې چې هغه راغلی نه وي خلک به ډوډۍ ونه خوري، ځکه چې هغه باید اول قربانۍ ته برکت ورکړي. وروسته به رابلل شوي خلک ډوډۍ وخوري. اوس پورته وخېژئ، نو په همدې وخت کې به یې پیدا کړئ.»', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30192, 'Esther 9:7', 'Esther', 9, 7, 'همدارنګه هغوی فرشنداطا، دلفون، اسفاتا،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30193, 'Esther 9:8', 'Esther', 9, 8, 'فوراتا، ادلیا، اریداتا،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30194, 'Esther 9:9', 'Esther', 9, 9, 'فرمشتا، اریسای، اریدای او ویزاتا هم ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30195, 'Esther 9:10', 'Esther', 9, 10, 'دا د همداتا د زوی هامان یعنې د یهودیانو د دښمن لس زامن وو. خو هغوی هېڅ شی لوټ نه کړ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30196, 'Numbers 1:5', 'Numbers', 1, 5, 'دا د هغو مشرانو نومونه دي چې تاسو سره باید مرسته وکړي: د روبین د قبیلې څخه الیصور د شدییور زوی', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30197, 'Numbers 1:6', 'Numbers', 1, 6, 'د شمعون د قبیلې څخه شلومی ییل د صوریشدای زوی', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30198, 'Numbers 1:7', 'Numbers', 1, 7, 'د یهودا د قبیلې څخه نحشون د عمیناداب زوی', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30199, 'Numbers 1:8', 'Numbers', 1, 8, 'د یساکار د قبیلې څخه نتناییل د صوغر زوی', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(30200, 'Numbers 1:9', 'Numbers', 1, 9, 'د زبولون د قبیلې څخه الیاب د حیلون زوی', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');